202	// 停用与保养：停用不改变计划内容、间隔或下一到期日；停用期间不能登记完成，
203	// 但可建立计划、撤销已登记完成；due 排除停用资产，恢复后按保存的下一到期日
204	// 参与查询（逾期显示原到期日），随后完成沿用原推进规则。
205	func TestDeactivationMaintenance(t *testing.T) {
