227		if rows := s.duePlans("2027-01-01"); len(rows) != 0 {
228			t.Fatalf("停用资产不应出现在 due 结果中，得到 %+v", rows)
229		}
230	
231		// 恢复后逾期计划按保存的下一到期日参与查询。
232		if _, err := s.reactivateAsset("EQ-1", "恢复使用"); err != nil {
233			t.Fatal(err)
234		}
235		rows := s.duePlans("2027-01-01")
236		if len(rows) != 1 || rows[0].Due != "2026-11-01" {
237			t.Fatalf("恢复后逾期计划应按原到期日显示，得到 %+v", rows)
238		}
239	
240		// 随后完成沿用首次到期日 + 间隔推进规则（延期跨周期不补记录）。
241		p2, next, seq, err := s.completePlan("EQ-1", "2026-11-01", "2026-11-03", "已更换滤芯")
242		if err != nil {
