246			t.Fatalf("完成后下一到期日 = %q 序号 = %d", next, seq)
247		}
248		_ = p2
249	
250		// 停用期间可按原规则撤销已登记完成，下一到期日恢复。
251		if _, err := s.deactivateAsset("EQ-1", "再次停用"); err != nil {
252			t.Fatal(err)
253		}
254		pp, target, err := s.revokeCompletion("EQ-1", seq, "误登记，实际未保养")
