257		}
258		if pp.NextDue != target.Due || pp.NextDue != "2026-11-01" {
259			t.Fatalf("撤销后应恢复周期到期日 2026-11-01，得到 %q", pp.NextDue)
260		}
261		// 计划内容、间隔未受停用影响。
262		if pp.IntervalDays != 90 || pp.FirstDue != "2026-11-01" || pp.Content != "更换滤芯" {
263			t.Fatalf("停用不应改变计划内容/间隔/首次到期日: %+v", pp)
