265		if _, _, _, err := s.completePlan("EQ-1", "2026-11-01", "2026-11-03", "已更换"); !errors.Is(err, errConflict) {
266			t.Fatalf("停用期间重新完成仍应拒绝，得到 %v", err)
267		}
