497			{
498				name: "停用期间新报修",
499				ledger: func() map[string]any {
500					m := base("停用", append(append([]any{}, closedTicket...),
501						map[string]any{"id": "T0002", "asset_id": "EQ-1", "description": "停用期间故障",
502							"request_id": "req-2", "status": "已关闭", "created_at": "2026-10-02T08:00:00Z",
503							"result": "已修复", "closed_at": "2026-10-02T10:00:00Z"}),
504						[]any{
505							map[string]any{"seq": 1, "asset_id": "EQ-1", "ticket_id": "T0001",
506								"kind": "报修", "content": "卡纸", "time": "2026-10-01T08:00:00Z"},
507							map[string]any{"seq": 2, "asset_id": "EQ-1", "ticket_id": "T0001",
508								"kind": "关闭", "content": "已修复", "time": "2026-10-01T09:00:00Z"},
509							map[string]any{"seq": 3, "asset_id": "EQ-1", "kind": "停用",
510								"content": "停用", "from": "可用", "to": "停用", "time": "2026-10-01T10:00:00Z"},
511							map[string]any{"seq": 4, "asset_id": "EQ-1", "ticket_id": "T0002",
512								"kind": "报修", "content": "停用期间故障", "time": "2026-10-02T08:00:00Z"},
513							map[string]any{"seq": 5, "asset_id": "EQ-1", "ticket_id": "T0002",
514								"kind": "关闭", "content": "已修复", "time": "2026-10-02T10:00:00Z"},
515						})
516					m["requests"] = append(requests,
517						map[string]any{"request_id": "req-2", "asset_id": "EQ-1", "description": "停用期间故障", "ticket_id": "T0002"})
518					m["next_ticket_seq"] = 3
519					return m
