524				ledger: base("停用", closedTicket, []any{
525					map[string]any{"seq": 1, "asset_id": "EQ-1", "ticket_id": "T0001",
526						"kind": "报修", "content": "卡纸", "time": "2026-10-01T08:00:00Z"},
527					map[string]any{"seq": 2, "asset_id": "EQ-1", "ticket_id": "T0001",
528						"kind": "关闭", "content": "已修复", "time": "2026-10-01T09:00:00Z"},
529				}),
530			},
531			{
532				name: "停用履历原状态错误",
533				ledger: base("停用", closedTicket, []any{
534					map[string]any{"seq": 1, "asset_id": "EQ-1", "ticket_id": "T0001",
535						"kind": "报修", "content": "卡纸", "time": "2026-10-01T08:00:00Z"},
536					map[string]any{"seq": 2, "asset_id": "EQ-1", "ticket_id": "T0001",
537						"kind": "关闭", "content": "已修复", "time": "2026-10-01T09:00:00Z"},
538					map[string]any{"seq": 3, "asset_id": "EQ-1", "kind": "停用",
539						"content": "停用", "from": "维修中", "to": "停用", "time": "2026-10-01T10:00:00Z"},
540				}),
541			},
542			{
543				name: "未停用却恢复",
544				ledger: base("可用", closedTicket, []any{
545					map[string]any{"seq": 1, "asset_id": "EQ-1", "ticket_id": "T0001",
546						"kind": "报修", "content": "卡纸", "time": "2026-10-01T08:00:00Z"},
547					map[string]any{"seq": 2, "asset_id": "EQ-1", "ticket_id": "T0001",
548						"kind": "关闭", "content": "已修复", "time": "2026-10-01T09:00:00Z"},
549					map[string]any{"seq": 3, "asset_id": "EQ-1", "kind": "恢复使用",
550						"content": "恢复", "from": "停用", "to": "可用", "time": "2026-10-01T10:00:00Z"},
551				}),
552			},
553			{
554				name: "停用期间登记保养完成",
555				ledger: func() map[string]any {
556					m := base("停用", closedTicket, []any{
557						map[string]any{"seq": 1, "asset_id": "EQ-1", "ticket_id": "T0001",
558							"kind": "报修", "content": "卡纸", "time": "2026-10-01T08:00:00Z"},
559						map[string]any{"seq": 2, "asset_id": "EQ-1", "ticket_id": "T0001",
560							"kind": "关闭", "content": "已修复", "time": "2026-10-01T09:00:00Z"},
561						map[string]any{"seq": 3, "asset_id": "EQ-1", "kind": "保养建立",
562							"content": "更换滤芯", "due": "2026-11-01", "interval": 90,
563							"time": "2026-10-01T12:00:00Z"},
564						map[string]any{"seq": 4, "asset_id": "EQ-1", "kind": "停用",
565							"content": "停用", "from": "可用", "to": "停用", "time": "2026-10-02T08:00:00Z"},
566						map[string]any{"seq": 5, "asset_id": "EQ-1", "kind": "保养完成",
567							"content": "已更换", "due": "2026-11-01", "done": "2026-11-03",
568							"time": "2026-11-03T08:00:00Z"},
569					})
570					m["plans"] = []any{
571						map[string]any{"asset_id": "EQ-1", "content": "更换滤芯", "first_due": "2026-11-01",
572							"interval_days": 90, "next_due": "2027-01-30"},
573					}
574					return m
575				}(),
576			},
577		}
578	
579		for _, tc := range cases {
580			t.Run(tc.name, func(t *testing.T) {
581				dir := t.TempDir()
582				raw := mustMarshal(t, tc.ledger)
583				path := filepath.Join(dir, dataFileName)
584				if err := os.WriteFile(path, raw, 0o644); err != nil {
585					t.Fatal(err)
586				}
