588					t.Fatalf("矛盾台账应加载失败: %s", tc.name)
589				}
590				// 读命令与写命令都拒绝，退出码 1，原文件字节不变。
591				var out, errBuf bytes.Buffer
592				if code := run([]string{"list", "--data-dir", dir}, &out, &errBuf); code != 1 {
593					t.Fatalf("矛盾台账 list 应退出 1，得到 %d", code)
594				}
595				if code := run([]string{"reactivate", "--data-dir", dir,
596					"--asset-id", "EQ-1", "--reason", "恢复"}, &out, &errBuf); code != 1 {
597					t.Fatalf("矛盾台账 reactivate 应退出 1，得到 %d", code)
598				}
599				got, err := os.ReadFile(path)
600				if err != nil {
601					t.Fatal(err)
602				}
603				if !bytes.Equal(got, raw) {
