610	// 导入连同停用/恢复履历与当前状态复制；履历重编号、顺序与时间精度保留，
611	// 整批冲突拒绝；导入后可继续恢复或停用，源只读。
612	func TestImportDeactivationContinuation(t *testing.T) {
613		srcDir := filepath.Join(t.TempDir(), "src")
614		dstDir := filepath.Join(t.TempDir(), "dst")
615	
616		src := newStoreAt(t, srcDir)
617		for _, a := range [][3]string{
618			{"EQ-OFF", "封存打印机", "仓库"}, {"EQ-ON", "空调", "二楼"},
619		} {
620			if _, err := src.registerAsset(a[0], a[1], a[2]); err != nil {
621				t.Fatal(err)
622			}
623		}
624		// EQ-OFF：报修→关闭→停用（最终停用）；EQ-ON：保持可用。
625		tk, _, err := src.report("EQ-OFF", "卡纸", "req-off")
626		if err != nil {
627			t.Fatal(err)
628		}
629		if _, _, err := src.closeTicket(tk.ID, "已修复"); err != nil {
630			t.Fatal(err)
631		}
632		if _, err := src.deactivateAsset("EQ-OFF", "调拨停用"); err != nil {
633			t.Fatal(err)
634		}
635		mustSave(t, src)
636		srcBefore := readFileBytes(t, srcDir)
637	
638		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-OFF", "EQ-ON"})
639		if err != nil {
640			t.Fatalf("导入失败: %v", err)
641		}
642		// 履历应整体重编号（源 3 条 → 目标 1..3），停用履历在其中。
643		if len(outcome.assetIDs) != 2 {
644			t.Fatalf("应导入 2 项资产，得到 %d", len(outcome.assetIDs))
645		}
646		if got := readFileBytes(t, srcDir); !bytes.Equal(got, srcBefore) {
647			t.Fatal("源台账应保持只读，字节不变")
648		}
649	
650		dst := newStoreAt(t, dstDir)
651		if got := dst.findAsset("EQ-OFF").Status; got != statusDeactivated {
652			t.Fatalf("导入资产应保持停用状态，得到 %q", got)
653		}
654		if got := dst.findAsset("EQ-ON").Status; got != statusAvailable {
655			t.Fatalf("导入资产应保持可用状态，得到 %q", got)
656		}
657		evs := dst.eventsOf("EQ-OFF")
658		if len(evs) != 3 || evs[2].Kind != eventDeactivate ||
659			evs[2].From != statusAvailable || evs[2].To != statusDeactivated {
660			t.Fatalf("停用履历应随导入复制并重编号: %+v", evs)
661		}
662		if evs[0].Seq != 1 || evs[2].Seq != 3 {
663			t.Fatalf("履历应在目标从 1 开始重编号，得到 %d..%d", evs[0].Seq, evs[2].Seq)
664		}
665	
666		// 导入后可继续恢复使用；请求重放返回映射后的原工单及当前状态。
667		if _, err := dst.reactivateAsset("EQ-OFF", "恢复使用"); err != nil {
668			t.Fatalf("导入的停用资产应能恢复: %v", err)
669		}
670		mapped := outcome.tickets[0].NewID
671		old, replay, err := dst.report("EQ-OFF", "卡纸", "req-off")
672		if err != nil || !replay || old.ID != mapped || old.Status != ticketClosed {
673			t.Fatalf("导入后请求重放应返回映射工单 %s: %v replay=%v err=%v", mapped, old, replay, err)
674		}
675		// 导入的可用资产可继续停用。
676		if _, err := dst.deactivateAsset("EQ-ON", "停用"); err != nil {
677			t.Fatalf("导入的可用资产应能停用: %v", err)
678		}
679		if err := dst.save(); err != nil {
680			t.Fatal(err)
681		}
682		dst2, err := openStore(dstDir)
683		if err != nil {
684			t.Fatalf("接续操作后的台账应能重载: %v", err)
685		}
686		if dst2.findAsset("EQ-OFF").Status != statusAvailable ||
687			dst2.findAsset("EQ-ON").Status != statusDeactivated {
688			t.Fatalf("重载后状态不对: EQ-OFF=%s EQ-ON=%s",
689				dst2.findAsset("EQ-OFF").Status, dst2.findAsset("EQ-ON").Status)
690		}
691	
692		// 再次导入同一批资产按编号冲突整批拒绝，目标不变。
693		dstBefore := readFileBytes(t, dstDir)
694		if _, err := importAssets(dstDir, srcDir, []string{"EQ-OFF"}); !errors.Is(err, errConflict) {
695			t.Fatalf("重复导入应冲突拒绝，得到 %v", err)
696		}
697		if got := readFileBytes(t, dstDir); !bytes.Equal(got, dstBefore) {
698			t.Fatal("整批冲突拒绝时目标文件字节应不变")
699		}
700	}
701	
702	// CLI：命令输出、退出码与 list/detail/history 展示。
703	func TestDeactivateCLI(t *testing.T) {
704		dir := t.TempDir()
705		var out, errBuf bytes.Buffer
706	
707		runOrFail := func(codeWant int, args ...string) {
708			t.Helper()
709			out.Reset()
710			errBuf.Reset()
711			if code := run(args, &out, &errBuf); code != codeWant {
712				t.Fatalf("run %v 退出码 = %d，想得到 %d；stderr=%s", args, code, codeWant, errBuf.String())
713			}
714		}
715	
716		runOrFail(0, "register", "--data-dir", dir, "--asset-id", "EQ-001", "--name", "打印机", "--location", "一楼")
717	
718		// 参数错误退出 2。
719		runOrFail(2, "deactivate", "--data-dir", dir, "--asset-id", "EQ-001")
720		runOrFail(2, "reactivate", "--data-dir", dir, "--reason", "恢复")
721	
722		// 未知资产业务失败退出 1。
723		runOrFail(1, "deactivate", "--data-dir", dir, "--asset-id", "NOPE", "--reason", "停用")
724	
725		// 成功停用：显示资产编号与新状态。
726		runOrFail(0, "deactivate", "--data-dir", dir, "--asset-id", "EQ-001", "--reason", "设备调拨")
727		if s := out.String(); !strings.Contains(s, "EQ-001") || !strings.Contains(s, statusDeactivated) {
728			t.Fatalf("停用输出应含资产编号与新状态: %s", s)
729		}
730	
731		// list 显示停用状态。
732		runOrFail(0, "list", "--data-dir", dir)
733		if !strings.Contains(out.String(), statusDeactivated) {
734			t.Fatalf("list 应显示停用状态: %s", out.String())
735		}
736	
737		// detail 显示停用状态与计划区域。
738		runOrFail(0, "detail", "--data-dir", dir, "--asset-id", "EQ-001")
739		if !strings.Contains(out.String(), statusDeactivated) {
740			t.Fatalf("detail 应显示停用状态: %s", out.String())
741		}
742	
743		// 重复停用退出 1。
744		runOrFail(1, "deactivate", "--data-dir", dir, "--asset-id", "EQ-001", "--reason", "再次停用")
745	
746		// history 展示停用事件的原状态、新状态与理由。
747		runOrFail(0, "history", "--data-dir", dir, "--asset-id", "EQ-001")
748		h := out.String()
749		if !strings.Contains(h, eventDeactivate) || !strings.Contains(h, statusAvailable) ||
750			!strings.Contains(h, statusDeactivated) || !strings.Contains(h, "设备调拨") {
751			t.Fatalf("history 应展示停用事件: %s", h)
752		}
753	
754		// 停用期间新报修退出 1。
755		runOrFail(1, "report", "--data-dir", dir, "--asset-id", "EQ-001",
756			"--description", "停用期间故障", "--request-id", "req-x")
757	
758		// 恢复成功，history 追加恢复事件。
759		runOrFail(0, "reactivate", "--data-dir", dir, "--asset-id", "EQ-001", "--reason", "调拨回库")
760		if !strings.Contains(out.String(), statusAvailable) {
761			t.Fatalf("恢复输出应含可用状态: %s", out.String())
762		}
763		runOrFail(0, "history", "--data-dir", dir, "--asset-id", "EQ-001")
764		if !strings.Contains(out.String(), eventReactivate) {
765			t.Fatalf("history 应展示恢复使用事件: %s", out.String())
766		}
767	
768		// 恢复后新报修成功，且使用停用期间被拒绝的同一请求标识（此前未绑定）。
769		runOrFail(0, "report", "--data-dir", dir, "--asset-id", "EQ-001",
770			"--description", "停用期间故障", "--request-id", "req-x")
771		if !strings.Contains(out.String(), "T0001") {
772			t.Fatalf("恢复后重试应开出 T0001: %s", out.String())
773		}
774	}
